using System.CommandLine;using System.Text.Json;using Cis.Abstractions;using Microsoft.Extensions.DependencyInjection;
namespace Cis.Modules.Verify;public sealed class VerifyModule:ICisModule
{private static readonly JsonSerializerOptions J=new(JsonSerializerDefaults.Web){WriteIndented=true};public string Name=>"verify";public string Description=>"Compare planned and actual delivery, record evidence, validate gates, and capture human acceptance.";public void RegisterServices(IServiceCollection s)=>s.AddSingleton<VerifyService>();public void RegisterCommands(ICisCommandRegistry c,IServiceProvider p){var s=p.GetRequiredService<VerifyService>();var r=new Command(Name,Description);r.Subcommands.Add(Change("diff","Capture changed files from every workspace repository baseline.",s.Diff));r.Subcommands.Add(Change("compare","Compare planned repository and path targets with observed changes.",s.Compare));r.Subcommands.Add(Change("validate","Validate delivery gates, current snapshot, and evidence.",s.Validate));r.Subcommands.Add(Evidence(s));r.Subcommands.Add(Authority("accept","Record explicit human final verification acceptance.",s.Accept));r.Subcommands.Add(Authority("finalize","Complete lifecycle tasks, close the dossier, recapture, and accept atomically.",s.Finalize));c.Add(r);}private static Command Change(string n,string d,Func<string,string,VerifyResult>a){var c=new Command(n,d);var id=new Argument<string>("change-id");var repo=Repo();var f=Format();c.Arguments.Add(id);c.Options.Add(repo);c.Options.Add(f);c.SetAction(x=>Render(a(x.GetValue(repo)!,x.GetValue(id)!),x.GetValue(f)!));return c;}private static Command Evidence(VerifyService s){var c=new Command("evidence","Append one exact verification evidence row.");var id=new Argument<string>("change-id");var task=Req("--task");var check=Req("--check");var artifact=Req("--artifact");var result=Req("--result");var notes=new Option<string>("--notes"){DefaultValueFactory=_=>""};var repo=Repo();var f=Format();c.Arguments.Add(id);foreach(var o in new Option[]{task,check,artifact,result,notes,repo,f})c.Options.Add(o);c.SetAction(x=>Render(s.Evidence(x.GetValue(repo)!,x.GetValue(id)!,x.GetValue(task)!,x.GetValue(check)!,x.GetValue(artifact)!,x.GetValue(result)!,x.GetValue(notes)!),x.GetValue(f)!));return c;}private static Command Authority(string name,string description,Func<string,string,string,string,VerifyResult> action){var c=new Command(name,description);var id=new Argument<string>("change-id");var reviewer=Req("--reviewer");var reason=Req("--reason");var repo=Repo();var f=Format();c.Arguments.Add(id);foreach(var o in new Option[]{reviewer,reason,repo,f})c.Options.Add(o);c.SetAction(x=>Render(action(x.GetValue(repo)!,x.GetValue(id)!,x.GetValue(reviewer)!,x.GetValue(reason)!),x.GetValue(f)!));return c;}private static Option<string>Req(string n)=>new(n){Required=true};private static Option<string>Repo()=>new("--repo"){DefaultValueFactory=_=>Directory.GetCurrentDirectory()};private static Option<string>Format()=>new("--format"){DefaultValueFactory=_=>"human"};private static int Render(VerifyResult r,string f){if(f=="json")Console.WriteLine(JsonSerializer.Serialize(r,J));else if(f=="agent"){Console.WriteLine($"status={r.Status};exitCode={r.ExitCode};changeId={r.ChangeId};files={r.Snapshot?.Files.Count??0};repositories={r.Snapshot?.Repositories?.Count??0};findings={r.Findings.Count};applied={r.Applied.ToString().ToLowerInvariant()}");foreach(var x in r.Findings)Console.WriteLine($"finding={x.Severity}:{x.Code};message={x.Message.Replace(';',',')};path={x.Path??"none"}");}else if(f=="human"){Console.WriteLine($"Verification: {r.Status}; files={r.Snapshot?.Files.Count??0}; repositories={r.Snapshot?.Repositories?.Count??0}; findings={r.Findings.Count}");foreach(var x in r.Findings)Console.WriteLine($"{x.Severity.ToUpperInvariant()} {x.Code}: {x.Message}");}else return 2;return r.ExitCode;}}
